CREATE TABLE dpx_defaults(a text DEFAULT 'x', v varchar(10) DEFAULT 'y' CHECK (v <> ''), b bigint DEFAULT 0, n numeric DEFAULT 5, n2 numeric DEFAULT 1.50, i integer DEFAULT '7', j integer DEFAULT -3, t timestamp DEFAULT '2020-01-01 10:00', d date DEFAULT current_date, js jsonb DEFAULT '{"b": 1, "a":2}', bo boolean DEFAULT 't', nl text DEFAULT NULL, c char(3) DEFAULT 'ab', f float8 DEFAULT 1.5, k integer CHECK (k BETWEEN 1 AND 5), m text CHECK (m IN ('a', 'b')), o integer CHECK (o IS NOT NULL AND o <> 7), p text CHECK (p LIKE 'x%'), q integer CHECK (NOT (q > 3)), r integer DEFAULT 2 + 3, s text DEFAULT upper('a') || lower('B'), ts2 timestamp DEFAULT localtimestamp(2), u uuid DEFAULT gen_random_uuid(), w text DEFAULT current_user, x numeric(5,2) DEFAULT 0.5, y integer[] DEFAULT '{1,2}', z interval DEFAULT '1 day');
SELECT attname, pg_get_expr(adbin, adrelid) FROM pg_attrdef JOIN pg_attribute ON attrelid = adrelid AND attnum = adnum WHERE adrelid = 'dpx_defaults'::regclass ORDER BY adnum;
SELECT conname, pg_get_constraintdef(oid), pg_get_expr(conbin, conrelid) FROM pg_constraint WHERE conrelid = 'dpx_defaults'::regclass ORDER BY conname;
CREATE TABLE dpx_checks(b bigint CHECK (b > 0), n numeric CHECK (n > 1), n3 numeric CHECK (n3 > 1.5), f float8 CHECK (f > 1), v varchar(5) CHECK (upper(v) <> 'X'), s smallint CHECK (s > 1), t text CHECK (length(t) > 2), d date CHECK (d > '2020-01-01'), ts timestamp CHECK (ts < now()), x text CHECK (x IS NULL OR x = lower(x)), c char(2) CHECK (c <> 'a'), e integer CHECK (e % 2 = 0), g integer CHECK (g = -1), h integer CHECK (h IN (1, 2, 3)), i integer CHECK (i >= 0 AND i < 10 AND i <> 5), k text CHECK (k ~ '^a'), l boolean CHECK (l), m boolean CHECK (NOT l), o integer CHECK (o::text <> '1'), p integer CHECK (coalesce(p, 0) > 0), q integer[] CHECK (array_length(q, 1) > 0));
SELECT conname, pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'dpx_checks'::regclass ORDER BY conname;
SELECT constraint_name, check_clause FROM information_schema.check_constraints WHERE constraint_name LIKE 'dpx_checks_%' ORDER BY constraint_name;
CREATE FUNCTION dpx_concat(a text DEFAULT 'x', b integer DEFAULT 1) RETURNS text LANGUAGE sql RETURN a || b;
CREATE FUNCTION dpx_test(a integer, b numeric DEFAULT 2.5, c varchar DEFAULT 'q', d date DEFAULT current_date) RETURNS boolean LANGUAGE sql RETURN a > 0 AND b > 1 AND c <> '';
CREATE FUNCTION dpx_math(x integer) RETURNS integer LANGUAGE sql RETURN x * 2 + 1;
SELECT proname, pg_get_function_arguments(oid), pg_get_function_identity_arguments(oid), pg_get_functiondef(oid) FROM pg_proc WHERE proname LIKE 'dpx_%' ORDER BY proname;
SELECT proname, pg_get_expr(proargdefaults, 0) FROM pg_proc WHERE proname LIKE 'dpx_%' ORDER BY proname;
CREATE SEQUENCE dpx_sequence;
CREATE TABLE dpx_more(id serial, b bigserial, n integer DEFAULT nextval('dpx_sequence'), t timestamptz DEFAULT CURRENT_TIMESTAMP, t2 timestamp DEFAULT now(), d date DEFAULT 'now'::text::date, s text DEFAULT 'it''s', e text DEFAULT '', a text[] DEFAULT '{}', i integer DEFAULT 1 + 2 * 3, k numeric DEFAULT -1.5, m text DEFAULT concat('a', 'b'), x integer GENERATED ALWAYS AS (n * 2) STORED);
SELECT attname, pg_get_expr(adbin, adrelid) FROM pg_attrdef JOIN pg_attribute ON attrelid = adrelid AND attnum = adnum WHERE adrelid = 'dpx_more'::regclass ORDER BY adnum;
ALTER TABLE dpx_more ADD CONSTRAINT dpx_more_c1 CHECK (n > 0 AND (b < 100 OR i = 7));
ALTER TABLE dpx_more ADD CONSTRAINT dpx_more_c2 CHECK (s <> e AND length(s) BETWEEN 1 AND 10);
ALTER TABLE dpx_more ADD CONSTRAINT dpx_more_c3 CHECK (t2 > '2000-01-01'::timestamp);
SELECT conname, pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid = 'dpx_more'::regclass AND contype = 'c' ORDER BY conname;
DROP TABLE dpx_more;
DROP SEQUENCE dpx_sequence;
DROP FUNCTION dpx_concat, dpx_test, dpx_math;
DROP TABLE dpx_defaults, dpx_checks;
CREATE TABLE dpx_pretty(id integer, b integer, v varchar(5), n numeric, d boolean, k integer CHECK (k BETWEEN 1 AND 5), m text CHECK (m IN ('a', 'b')), o integer CHECK (o IS NOT NULL AND o <> 7), p text CHECK (p LIKE 'x%' OR NOT d), q integer CHECK ((q + 1) * 2 > 3 - (4 - b)), c2 integer CHECK (c2::text <> '1' AND n > 1));
SELECT conname, pg_get_constraintdef(oid, true), pg_get_expr(conbin, conrelid, true) FROM pg_constraint WHERE conrelid = 'dpx_pretty'::regclass ORDER BY conname;
DROP TABLE dpx_pretty;
CREATE TABLE dpx_objects(id integer PRIMARY KEY, a text, b integer, n numeric);
CREATE INDEX dpx_objects_partial ON dpx_objects (b) WHERE b > 0 AND a <> 'x';
CREATE UNIQUE INDEX dpx_objects_included ON dpx_objects (a) INCLUDE (b) WHERE n IS NOT NULL;
SELECT indexrelid::regclass, pg_get_indexdef(indexrelid), pg_get_indexdef(indexrelid, 0, true) FROM pg_index WHERE indrelid = 'dpx_objects'::regclass ORDER BY indexrelid::regclass::text;
CREATE FUNCTION dpx_trigger() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN NEW; END';
CREATE TRIGGER dpx_objects_when BEFORE INSERT OR UPDATE OF a ON dpx_objects FOR EACH ROW WHEN (NEW.b > 0 AND NEW.a IS NOT NULL) EXECUTE FUNCTION dpx_trigger();
SELECT pg_get_triggerdef(oid), pg_get_triggerdef(oid, true) FROM pg_trigger WHERE tgname = 'dpx_objects_when';
CREATE RULE dpx_objects_rule AS ON INSERT TO dpx_objects WHERE NEW.b < 0 DO INSTEAD NOTHING;
SELECT pg_get_ruledef(oid), pg_get_ruledef(oid, true) FROM pg_rewrite WHERE rulename = 'dpx_objects_rule';
DROP TABLE dpx_objects;
DROP FUNCTION dpx_trigger();
